function once(fn) {
  let called = false;
  let result;
  return function (...args) {
    if (!called) {
      called = true;
      result = fn.apply(this, args);
    }
    return result;
  };
}

const init = once(() => {
  console.log("expensive init");
  return { ready: true };
});
init(); init(); // logs once

function createFetcher(baseUrl, getHeaders) {
  return function fetchJson(path) {
    return fetch(`${baseUrl}${path}`, { headers: getHeaders() })
      .then((r) => r.json());
  };
}

const api = createFetcher("https://api.example.com", () => ({
  Authorization: "Bearer token"
}));
api("/users");

function debounce(fn, ms) {
  let timer;
  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), ms);
  };
}

const onSearch = debounce((q) => fetch(`/search?q=${q}`), 300);
// Without debounce: N fetches per N keys
// With debounce: one fetch after typing pauses

// Leak footgun: onSearch holds timer + closure until GC if
// you never clearTimeout on component teardown
